INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Können Stabsstellen direkte Anweisungen geben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur beratende Funktion"}, {"text": "Ja", "correct": false, "because": "Keine Weisungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spiele ich in dieser Struktur?', 3, '[{"text": "Berater", "correct": true, "because": "Fachliche Unterstützung"}, {"text": "Entscheider", "correct": false, "because": "Keine Befugnis"}, {"text": "Koordinator", "correct": false, "because": "Nur Beratung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernehme ich hier typischerweise?', 5, '[{"text": "Analysen erstellen", "correct": true, "because": "Daten für Entscheidungen"}, {"text": "Empfehlungen geben", "correct": true, "because": "Unterstützung der Linie"}, {"text": "Befehle erteilen", "correct": false, "because": "Keine Weisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Stabsstellen unterstützen die Führung. b) Sie haben Entscheidungsgewalt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Befugnis bei b)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich in einer Stabsrolle arbeite?', 4, '[{"text": "Fachwissen", "correct": false, "because": "Grundlage der Beratung"}, {"text": "Linienvorgaben", "correct": false, "because": "Richtlinien beachten"}, {"text": "Befehlsgewalt", "correct": true, "because": "Nicht Teil der Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Stabsstellen für kleine Firmen nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Auch dort hilfreiche Expertise"}, {"text": "Nein", "correct": false, "because": "Größe kein Ausschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat diese Rolle in einem Team?', 3, '[{"text": "Fachliche Expertise liefern", "correct": true, "because": "Unterstützt Entscheidungen"}, {"text": "Direkt steuern", "correct": false, "because": "Keine Weisung"}, {"text": "Konflikte lösen", "correct": false, "because": "Nicht primäre Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt diese Struktur?', 5, '[{"text": "Spezialisiertes Wissen", "correct": true, "because": "Experten unterstützen"}, {"text": "Entlastung der Linie", "correct": true, "because": "Fokus auf Führung"}, {"text": "Schnelle Befehle", "correct": false, "because": "Nur Beratung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Stabsstellen sind beratend. b) Sie übernehmen die Führung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Führungsrolle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht in dieser Position?', 4, '[{"text": "Analytische Fähigkeiten", "correct": false, "because": "Basis für Empfehlungen"}, {"text": "Kommunikation", "correct": false, "because": "Wissen vermitteln"}, {"text": "Direkte Autorität", "correct": true, "because": "Keine Weisungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Stabsstellen immer unwichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Wertvolle Unterstützung"}, {"text": "Ja", "correct": false, "because": "Fachwissen zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente definieren diese Rolle?', 4, '[{"text": "Fachkompetenz", "correct": true, "because": "Kern der Unterstützung"}, {"text": "Beratung", "correct": true, "because": "Hauptaufgabe"}, {"text": "Befehlsgewalt", "correct": false, "because": "Fehlt in der Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Stabsstellen nur Bürokratie erhöhen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können Effizienz steigern"}, {"text": "Ja", "correct": false, "because": "Abhängig von Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in dieser Rolle?', 3, '[{"text": "Präzise Analysen", "correct": true, "because": "Basis für gute Beratung"}, {"text": "Schnelle Entscheidungen", "correct": false, "because": "Nicht meine Aufgabe"}, {"text": "Teamsteuerung", "correct": false, "because": "Keine Weisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Stabsstellen haben kein Mitspracherecht. b) Sie liefern Expertise.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Mitsprache indirekt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stärken hat diese Struktur?', 5, '[{"text": "Fachliche Unterstützung", "correct": true, "because": "Expertenwissen"}, {"text": "Entlastung der Führung", "correct": true, "because": "Fokus bleibt"}, {"text": "Direkte Kontrolle", "correct": false, "because": "Keine Befugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier unwichtig?', 3, '[{"text": "Fachwissen", "correct": false, "because": "Kern der Rolle"}, {"text": "Empfehlungen", "correct": false, "because": "Hauptaufgabe"}, {"text": "Befehlsgewalt", "correct": true, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Stabsstellen Projekte leiten?', 3, '[{"text": "Nein", "correct": true, "because": "Nur beratend, keine Leitung"}, {"text": "Ja", "correct": false, "because": "Fehlende Befugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Rolle immer im Hintergrund bleibt?', 2, '[{"text": "Nein", "correct": true, "because": "Einfluss durch Expertise"}, {"text": "Ja", "correct": false, "because": "Sichtbar durch Beratung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe wähle ich, um die Linie zu unterstützen?', 4, '[{"text": "Daten analysieren", "correct": true, "because": "Fakten für Entscheidungen"}, {"text": "Befehle geben", "correct": false, "because": "Keine Weisung"}, {"text": "Team übernehmen", "correct": false, "because": "Nur Unterstützung"}]');
